	MOVD F14_COUNT(R0), R15
	MOVD RSP, R23           // scratch base for pass-1 filter8 results

	MOVD F14_LIMIT(R0), R16
	WORD $0x4e020e00 // dup v0.8h, w16
	MOVD F14_BLIMIT(R0), R17
	WORD $0x4e020e21 // dup v1.8h, w17
	MOVD F14_HEV(R0), R19
